 const {origin,db}=setup({},{token:false});
 const disabled=await login(origin,"synthetic-admin-test-password");expect(disabled.response.status).toBe(503);
 expect(disabled.value.error).toBe("Run `cubix-api admin-token` in the container to enable administration");
 expect((await fetch(origin+"/api/admin/overview")).status).toBe(503);
 const token=adminToken(db.path);expect(token).toMatch(/^cbx_admin_[0-9a-f]{64}$/);
 expect((await login(origin,"synthetic-admin-test-password")).response.status).toBe(401);
 expect((await login(origin,token)).response.status).toBe(200);
 // The upload password needs no token; the token opens no upload.
 const upload=(password:string)=>fetch(origin+"/api/mobile/updates",{method:"PUT",headers:{authorization:"Bearer "+password,"content-type":"application/json"},body:"{}"});
 expect((await upload(token)).status).toBe(401);expect((await upload("synthetic-admin-test-password")).status).not.toBe(401);
