 expect((await call(origin,"GET","/api/auth/me",{token:user.token,headers:from("203.0.113.20")})).status).toBe(200);
 await fetch(origin+"/nothing-here",{headers:from("203.0.113.20")});await fetch(origin+"/api/moves",{headers:from("203.0.113.21")});
 db.db.exec(`INSERT INTO traffic_daily(day,ip,requests,errors,server_errors,limited,first_at,last_at) VALUES('${dayAgo(10)}','198.51.100.9',7,1,0,3,1000,2000)`);
 const admin=await login(origin);const get=(query:string)=>adminGet(origin,admin.cookie,"/api/admin/ips"+query);
 const week=await get("");
 expect(week.days).toBe(7);expect(week.total).toBe(3);expect(week.rows.map((r:any)=>r.ip).sort()).toEqual(["127.0.0.1","203.0.113.20","203.0.113.21"]);
 const busy=week.rows.find((r:any)=>r.ip==="203.0.113.20");
 expect(busy).toMatchObject({requests:3,errors:1,serverErrors:0,limited:0,activeDays:1,userCount:1,users:[{id:user.user.id,username:"ip_user",isGuest:false}]});
 expect(busy.firstSeenAt).toBeLessThanOrEqual(busy.lastSeenAt);
 expect(week.rows.find((r:any)=>r.ip==="203.0.113.21").users).toEqual([]);
 const month=await get("?days=30");expect(month.total).toBe(4);expect(month.rows.find((r:any)=>r.ip==="198.51.100.9")).toMatchObject({requests:7,errors:1,limited:3});
 expect((await get("?days=30&sort=limited")).rows[0].ip).toBe("198.51.100.9");
 expect((await get("?sort=errors")).rows[0].ip).toBe("203.0.113.20");
 expect((await get("?sort=ip")).rows.map((r:any)=>r.ip)).toEqual(["127.0.0.1","203.0.113.20","203.0.113.21"]);
