test("finished duels are recorded for the overview and both accounts",async()=>{
 const {origin}=setup();const alice=await register(origin,"duel_alice");const bob=await register(origin,"duel_bob");
 async function player(token:string) {
  const ws=new WebSocket(origin.replace("http:","ws:")+"/api/duel");const inbox:any[]=[];ws.onmessage=({data})=>inbox.push(JSON.parse(String(data)));
  await new Promise(resolve=>(ws.onopen=resolve));cleanup.unshift(()=>ws.close());
  const next=async(test:(m:any)=>boolean)=>{for(let i=0;i<300;i++){const found=inbox.find(test);if(found)return found;await Bun.sleep(10);}throw Error("Missing duel message");};
  return {ws,next,send:(m:object)=>ws.send(JSON.stringify(m))};
 }
 const a=await player(alice.token),b=await player(bob.token);
 a.send({type:"queue",event:"333",level:10000,token:alice.token});b.send({type:"queue",event:"333",level:10500,token:bob.token});
 const [ma]=await Promise.all([a.next(m=>m.type==="match"),b.next(m=>m.type==="match")]);
 const [host,guest]=ma.host?[a,b]:[b,a];const aliceSeat=ma.seat;
 host.send({type:"scrambles",list:["R","U","F","L","D"]});await guest.next(m=>m.type==="state"&&m.scrambles.length===5);
 for(let round=0;round<5;round++){
  a.send({type:"solve",round,ms:10000+round,penalty:"none"});b.send({type:"solve",round,ms:12000+round,penalty:round===4?"dnf":"none"});
  await a.next(m=>m.type==="state"&&m.results.every((r:any[])=>r[round]));
 }
 a.ws.close();b.ws.close();
 const admin=await login(origin);
 const overview=await eventually(()=>adminGet(origin,admin.cookie,"/api/admin/overview"),o=>o.duels.total===1);
 expect(overview.duels).toEqual({total:1,today:1,d7:1});expect(overview.series.at(-1).duels).toBe(1);
 const detail=await adminGet(origin,admin.cookie,"/api/admin/users/"+alice.user.id);
 expect(detail.duels).toMatchObject({played:1,won:1,lost:0,recent:[{opponent:"duel_bob",opponentId:bob.user.id,ao5:10002,opponentAo5:12002,result:"win"}]});
 expect(detail.user.duels).toBe(1);expect(aliceSeat===0||aliceSeat===1).toBe(true);
 const log=await adminGet(origin,admin.cookie,"/api/admin/requests?kind=duel");expect(log.total).toBe(2);expect(log.rows[0]).toMatchObject({status:101,important:true});
});

test("rate-limited requests are logged as important and counted per day and per IP",async()=>{
 // The admin's own IP shares the limit: the start-up health probe, the login and four reads fit.
 const {origin}=setup({CUBIX_TRUSTED_PROXIES:"127.0.0.1",CUBIX_RATE_LIMIT:"8"});
 const statuses=[];for(let i=0;i<10;i++)statuses.push((await fetch(origin+"/api/moves",{headers:{"x-forwarded-for":"203.0.113.30"}})).status);
 expect(statuses.filter(s=>s===429).length).toBeGreaterThanOrEqual(2);const limited=statuses.filter(s=>s===429).length;
 const admin=await login(origin);
 const log=await adminGet(origin,admin.cookie,"/api/admin/requests?kind=rate-limit");
 expect(log.total).toBe(limited);expect(log.rows[0]).toMatchObject({ip:"203.0.113.30",status:429,important:true,path:"/api/moves"});
 expect((await adminGet(origin,admin.cookie,"/api/admin/requests?important=0&ip=203.0.113.30")).total).toBe(10-limited);
 expect((await adminGet(origin,admin.cookie,"/api/admin/overview")).requests).toMatchObject({rateLimitedToday:limited,errorsToday:limited});
 expect((await adminGet(origin,admin.cookie,"/api/admin/ips?sort=limited")).rows[0]).toMatchObject({ip:"203.0.113.30",requests:10,limited,errors:limited});
});
